/**
 * What the compiler consumed of the spec, and the refusal of everything it did not.
 *
 * `validate.ts` says which Vega-Lite properties may appear; this module makes sure that each one that does appear is READ by the
 * compiler. A property that is accepted and never read is a feature compiled silently wrong (the compiler goes on as if it were not
 * there), so the compile refuses it instead, with a VLCompileError naming its path. The list of what is refused is generated by the
 * code that compiles, not remembered beside it.
 *
 * How it works. The compile's copy of the spec is armed while it is made (rows.ts cloneSpecStructure with `ARMING`): every property
 * of every object that does not hold properties of its own is an accessor whose first read records it as consumed.
 * `refuseUnconsumed`, at the end of the compile, throws for the properties that were never read. A write without a read does not
 * consume (the user's value was dropped; the property becomes ordinary data); a `delete` does not either.
 *
 * What must be read. A property whose value is an object (a channel definition, an axis, a layer) or an array of objects stands for
 * what is inside it: it is consumed when any property below it is, so code that moves such values around (normalizing a facet, a
 * layer, a composite mark) needs no bookkeeping for them. A property whose value is a scalar, an array of scalars or an empty object
 * must be read itself. An object none of whose properties is read is refused property by property.
 *
 * Reading a property is consuming it, whatever the read is: `spec.width`, a destructuring, `Object.entries`, a spread, a
 * `JSON.stringify`. The primitives below keep that honest where a read is not a use, or where a value moves:
 *  - `peek(f)`: what `f` reads is not consumed (a comparison, a cache key, a decision on the spec's shape that compiles nothing).
 *  - `derive(src, over)`, `deriveWithout(src, keys)`, `pick(src, keys)`, `transfer(src, key, dst)`: copies of `src`'s properties
 *    that stand for `src`'s until the COPY's are read. Use them, not a spread or a destructuring, where a spec object is rewritten to
 *    be compiled further.
 *  - `merge(base, top)`: `{...base, ...top}` of two spec objects where `top` overrides `base` as vega-lite's merges do: an overridden
 *    property of `base` is consumed (it has no effect in vega-lite either).
 *  - `ignore(obj, key, why)`: consumed without being read, where vega-lite itself ignores the property (the reason is the
 *    documentation, and a test against vega-lite pins it).
 *  - `consumeAll(node)`: everything below `node` is forwarded to Vega as it is.
 *
 * What it costs. The check runs in every compile, so it is built to cost little: the spec is armed while it is copied (no second
 * copy), each object keeps its state in one hidden record of arrays (no object per property), every tracked object shares one accessor
 * per key name (objects of one shape keep sharing one hidden class), and the paths of a refusal are only worked out when there is
 * something to refuse.
 *
 * See packages/vl/CONTRIBUTING.md ("The consumption check") for how to adopt it in a compile function.
 */
import { VLCompileError } from './names.js'

type Obj = Record<string, unknown>

/** An armed property the compile has to read (a leaf of the spec): it counts in `unread` until it is consumed. */
const TRACKED = 1
/** Read here (a copy's first read consumes what it stands for; later reads of it cost nothing more). */
const DONE = 2
/** (an armed entry) Consumed, by a read of it or of any copy of it. */
const CONSUMED = 4
/** Written over: the property is data and holds something else now. */
const STALE = 8

/**
 * The state of one object's tracked properties: its hidden record.
 *
 * Entries `[0, armed)` are the object's own properties as the spec has them, in the spec's order, every one of them (on an armed object
 * of the spec; `armed` is 0 on any other object): the refusal walks the spec through them, and those that are `TRACKED` are the ones it
 * reports. Entries from `armed` on are copies (`derive`, `transfer` ...): entry `i` stands for the armed entry `at[i]` of `from[i]`. A key
 * may have several entries (a copy put over a property): the last is the live one, which the property's accessor reads; an earlier
 * one keeps the state of what was put over (an armed property overwritten unread is still refused).
 */
interface Rec {
  readonly t: Tracking
  readonly keys: string[]
  readonly values: unknown[]
  readonly flags: number[]
  readonly armed: number
  from: Rec[] | undefined
  at: number[] | undefined
}

interface Tracking {
  /** the armed spec */
  root: object | undefined
  /** how many armed properties are not consumed yet */
  unread: number
  /** each armed array -> its elements as they were armed (the compile may edit the array; the refusal walks the spec as it was) */
  readonly arrays: Map<unknown[], { readonly elements: readonly unknown[]; readonly holds: boolean }>
  peeking: number
}

let active: Tracking | undefined

/** Where an object keeps its record: one hidden (non-enumerable, symbol-keyed) property. */
const REC = Symbol('aster.vl.consume')
type Tracked = { [REC]?: Rec }
const recOf = (obj: object): Rec | undefined => (obj as Tracked)[REC]

function attach(obj: object, rec: Rec): void {
  Object.defineProperty(obj, REC, { value: rec, writable: true, enumerable: false, configurable: true })
}

/** Run `f` (one compile pass) with consumption tracking: `ARMING` and the primitives act on this pass's spec. */
export function withConsumption<T>(f: () => T): T {
  const saved = active
  active = { root: undefined, unread: 0, arrays: new Map(), peeking: 0 }
  try {
    return f()
  } finally {
    active = saved
  }
}

/** Entry `i` of `r` is read: it, and the armed property it stands for, are consumed. */
function consumeAt(r: Rec, i: number): void {
  r.flags[i]! |= DONE
  let o = r
  let j = i
  if (i >= r.armed) {
    o = r.from![i]!
    j = r.at![i]!
  }
  if ((o.flags[j]! & CONSUMED) !== 0) return
  o.flags[j]! |= CONSUMED | DONE
  o.t.unread--
  // (a debugging hook for compiler work: who consumed a property; CONTRIBUTING.md "The consumption check")
  const trace = (globalThis as { __consumeTrace?: (path: string | undefined, stack: string | undefined) => void }).__consumeTrace
  if (trace !== undefined) trace(pathOf(o.t, o, j), new Error().stack)
}

/** One accessor per key name, shared by every tracked object (objects of one shape share one hidden class): it reads the object's record. */
const ACCESSORS = new Map<string, PropertyDescriptor>()
function accessorFor(key: string): PropertyDescriptor {
  let d = ACCESSORS.get(key)
  if (d === undefined) {
    d = {
      enumerable: true,
      configurable: true,
      get(this: Tracked): unknown {
        const r = this[REC]!
        const i = r.keys.lastIndexOf(key)
        if ((r.flags[i]! & DONE) === 0 && (active !== r.t || r.t.peeking === 0)) consumeAt(r, i)
        return r.values[i]
      },
      // (a write: the property becomes ordinary data, and what it held is not consumed by it)
      set(this: Tracked, v: unknown): void {
        const r = this[REC]!
        r.flags[r.keys.lastIndexOf(key)]! |= STALE
        Object.defineProperty(this, key, { value: v, writable: true, enumerable: true, configurable: true })
      },
    }
    ACCESSORS.set(key, d)
  }
  return d
}

/** `out[key] = value` as data, a `__proto__` key too (an own key, never the prototype). */
function setData(out: Obj, key: string, value: unknown): void {
  if (key === '__proto__') Object.defineProperty(out, key, { value, writable: true, enumerable: true, configurable: true })
  else out[key] = value
}

/** Does `v` hold properties the check follows: an armed object with keys, or an armed array that holds one? */
function holds(t: Tracking, v: unknown): boolean {
  if (v === null || typeof v !== 'object') return false
  if (Array.isArray(v)) return t.arrays.get(v)?.holds === true
  const r = recOf(v)
  return r !== undefined && r.t === t && r.armed > 0
}

/**
 * How rows.ts cloneSpecStructure arms the copy it makes, in a compile with tracking: `object` gives each copied object (a fresh, empty
 * `dict`) its properties, the values already copied (and armed); `array` registers each copied array; `root` the copy. Outside a compile
 * with tracking, `object` makes ordinary data.
 */
export interface SpecArming {
  object(out: Obj, keys: string[], values: unknown[]): void
  array(a: unknown[]): void
  root(o: Obj): void
}

export const ARMING: SpecArming = {
  object(out, keys, values) {
    const t = active
    const n = keys.length
    if (t === undefined) {
      for (let i = 0; i < n; i++) setData(out, keys[i]!, values[i])
      return
    }
    const flags = new Array<number>(n)
    attach(out, { t, keys, values, flags, armed: n, from: undefined, at: undefined })
    // (one definition per property, in the spec's order: what a compile names after the order of a spec's keys - a bin's
    // `bin_maxbins_6_extent_param_brush_v` - is named as vega-lite names it)
    for (let i = 0; i < n; i++) {
      const key = keys[i]!
      const value = values[i]
      // (a property that holds properties is consumed through them: it is data, and a read of it stays a plain read)
      if (holds(t, value)) {
        flags[i] = 0
        setData(out, key, value)
      } else {
        flags[i] = TRACKED
        t.unread++
        Object.defineProperty(out, key, accessorFor(key))
      }
    }
  },
  array(a) {
    const t = active
    if (t === undefined) return
    let h = false
    for (let i = 0; i < a.length && !h; i++) h = holds(t, a[i])
    t.arrays.set(a, { elements: a.slice(), holds: h })
  },
  root(o) {
    if (active !== undefined) active.root = o
  },
}

/**
 * Arm `root`, a plain copy of a spec (`dict`s and arrays), as a compile's copy is armed (for tests: compile arms the copy while it makes
 * it). `skip` says which values are not spec structure: they are kept as they are and not entered (the property that holds them is
 * tracked). Returns the armed copy.
 */
export function arm<T extends Obj>(root: T, skip: (v: unknown) => boolean): T {
  if (active === undefined) return root
  const made = new Map<object, unknown>()
  const rebuild = (node: unknown): unknown => {
    if (node === null || typeof node !== 'object' || skip(node)) return node
    const have = made.get(node)
    if (have !== undefined) return have
    if (Array.isArray(node)) {
      const out = node.map(rebuild)
      made.set(node, out)
      ARMING.array(out)
      return out
    }
    const keys = Object.keys(node)
    const out = Object.create(Object.getPrototypeOf(node) as object | null) as Obj
    ARMING.object(out, keys, keys.map((k) => rebuild((node as Obj)[k])))
    made.set(node, out)
    return out
  }
  const armed = rebuild(root) as T
  ARMING.root(armed)
  return armed
}

/** `obj[key]`, not consumed (a `peek` of one read, without a closure). */
function peekAt(t: Tracking | undefined, obj: Obj, key: string): unknown {
  if (t === undefined) return obj[key]
  t.peeking++
  try {
    return obj[key]
  } finally {
    t.peeking--
  }
}

/** Run `f` without consuming what it reads. */
export function peek<T>(f: () => T): T {
  const t = active
  if (t === undefined) return f()
  t.peeking++
  try {
    return f()
  } finally {
    t.peeking--
  }
}

/** Run `f` consuming what it reads, also inside a `peek` (a rewrite that peeks at the spec's shape, around code that uses the spec). */
export function consuming<T>(f: () => T): T {
  const t = active
  if (t === undefined || t.peeking === 0) return f()
  const saved = t.peeking
  t.peeking = 0
  try {
    return f()
  } finally {
    t.peeking = saved
  }
}

/**
 * The live entry of `obj[key]` (`r` is `obj`'s record) in tracking `t`: its index when the property still holds the tracked value (not
 * written over, nor deleted and assigned again) and stands for an armed property; -1 when it is data.
 */
function liveEntry(t: Tracking, r: Rec | undefined, obj: Obj, key: string): number {
  if (r === undefined || r.t !== t) return -1
  const i = r.keys.lastIndexOf(key)
  if (i < 0 || (r.flags[i]! & STALE) !== 0 || (i < r.armed && (r.flags[i]! & TRACKED) === 0)) return -1
  return peekAt(t, obj, key) === r.values[i] ? i : -1
}

/** Make `dst[key]` a tracked property holding `value`, standing for what the live entry `i` of `r` stands for. */
function track(t: Tracking, dst: Obj, key: string, value: unknown, r: Rec, i: number): void {
  const o = i < r.armed ? r : r.from![i]!
  const j = i < r.armed ? i : r.at![i]!
  let d = recOf(dst)
  if (d === undefined || d.t !== t) {
    d = { t, keys: [], values: [], flags: [], armed: 0, from: undefined, at: undefined }
    attach(dst, d)
  }
  const k = d.keys.length
  d.keys.push(key)
  d.values.push(value)
  d.flags.push(0)
  ;(d.from ??= [])[k] = o
  ;(d.at ??= [])[k] = j
  Object.defineProperty(dst, key, accessorFor(key))
}

/** Copy `src[key]` onto `dst[as]`, still standing for what `src[key]` stands for. */
function copyProp(t: Tracking | undefined, src: Obj, key: string, dst: Obj, as = key): void {
  if (t !== undefined) {
    const r = recOf(src)
    const i = liveEntry(t, r, src, key)
    if (i >= 0) {
      track(t, dst, as, r!.values[i], r!, i)
      return
    }
  }
  setData(dst, as, peekAt(t, src, key))
}

const blank = (like: object): Obj => Object.create(Object.getPrototypeOf(like) as object | null) as Obj

/**
 * `{...src, ...over}` for a spec object that is compiled further: a property copied from `src` is consumed when the copy's is read.
 * (A property of `src` that `over` replaces is not consumed by this: the code that computed `over` read it, or it is refused.)
 */
export function derive<T extends Obj>(src: T, over?: Obj): T {
  const t = active
  const out = blank(src)
  for (const key of Object.keys(src)) if (over === undefined || !Object.hasOwn(over, key)) copyProp(t, src, key, out)
  if (over !== undefined) for (const key of Object.keys(over)) copyProp(t, over, key, out)
  return out as T
}

/** A deep copy of a spec value (in place of `structuredClone` of a spec object), every copied property still tracked. */
export function deriveDeep<T>(v: T): T {
  if (Array.isArray(v)) return v.map(deriveDeep) as T
  if (v === null || typeof v !== 'object') return v
  const t = active
  const src = v as Obj
  const out = blank(src)
  for (const key of Object.keys(src)) {
    const inner = peekAt(t, src, key)
    if (inner === null || typeof inner !== 'object') {
      copyProp(t, src, key, out)
      continue
    }
    // (an object below is copied too; its property here still stands for the original's)
    const copy = deriveDeep(inner)
    const r = t !== undefined ? recOf(src) : undefined
    const i = t !== undefined ? liveEntry(t, r, src, key) : -1
    if (i >= 0) track(t!, out, key, copy, r!, i)
    else setData(out, key, copy)
  }
  return out as T
}

/** `src` without the properties `omit` (in place of `const {a, b, ...rest} = src` when `rest` is compiled further). */
export function deriveWithout<T extends Obj>(src: T, omit: readonly string[]): T {
  const t = active
  const out = blank(src)
  for (const key of Object.keys(src)) if (!omit.includes(key)) copyProp(t, src, key, out)
  return out as T
}

/** The properties `keys` of `src` that it has (and are not undefined) on a new object, or on `into`, still tracked. */
export function pick(src: Obj, keys: readonly string[], into?: Obj): Obj {
  const t = active
  const out = into ?? blank(src)
  for (const key of keys) if (Object.hasOwn(src, key) && peekAt(t, src, key) !== undefined) copyProp(t, src, key, out)
  return out
}

/** `dst[as] = src[key]`, still tracked (a property that moves to another object). */
export function transfer(src: Obj, key: string, dst: Obj, as = key): void {
  if (Object.hasOwn(src, key)) copyProp(active, src, key, dst, as)
}

/**
 * `{...base, ...top}` of two spec objects where `top` overrides `base` as vega-lite's merges do (a layer's encoding under a unit's, a
 * config block under a mark def): a property of `base` that `top` overrides is consumed (it has no effect in vega-lite either).
 */
export function merge(base: Obj, top: Obj): Obj {
  const t = active
  const out = blank(top)
  for (const key of Object.keys(base)) {
    if (Object.hasOwn(top, key)) ignore(base, key, 'overridden')
    else copyProp(t, base, key, out)
  }
  for (const key of Object.keys(top)) copyProp(t, top, key, out)
  return out
}

/** Consume `obj[key]`, and everything below it, without reading it, where vega-lite ignores the property too (`why` says so; a test pins it). */
export function ignore(obj: Obj, key: string, _why: string): void {
  const t = active
  if (t === undefined) return
  const r = recOf(obj)
  const i = liveEntry(t, r, obj, key)
  if (i >= 0) consumeAt(r!, i)
  consumeAll(i >= 0 ? r!.values[i] : peekAt(t, obj, key))
}

/**
 * Consume what is still unread of `obj` (each such property and everything below it), where the code that reads `obj` reads what
 * vega-lite reads of it and vega-lite reads nothing else (`why` says where; a test pins it).
 */
export function ignoreUnread(obj: Obj, why: string, only?: readonly string[]): void {
  const t = active
  if (t === undefined) return
  const r = recOf(obj)
  if (r === undefined || r.t !== t) return
  // (each key once, by its live entry)
  for (const key of new Set(r.keys)) {
    if (only !== undefined && !only.includes(key)) continue
    const i = r.keys.lastIndexOf(key)
    if (i < r.armed && (r.flags[i]! & TRACKED) === 0) continue
    const o = i < r.armed ? r : r.from![i]!
    const j = i < r.armed ? i : r.at![i]!
    if ((o.flags[j]! & CONSUMED) === 0) ignore(obj, key, why)
  }
}

/** Consume everything below `node`: it is forwarded to Vega as it is. */
export function consumeAll(node: unknown): void {
  const t = active
  if (t === undefined) return
  const seen = new Set<object>()
  const visit = (n: unknown): void => {
    if (n === null || typeof n !== 'object' || seen.has(n)) return
    seen.add(n)
    if (Array.isArray(n)) {
      n.forEach(visit)
      return
    }
    // (the properties of an armed object, and those a copy stands for: each key's live entry, written over or not)
    const r = recOf(n)
    if (r !== undefined && r.t === t) {
      for (let i = 0; i < r.keys.length; i++) {
        if (i < r.armed && (r.flags[i]! & TRACKED) === 0) continue
        if (r.keys.lastIndexOf(r.keys[i]!) === i) consumeAt(r, i)
      }
    }
    for (const k of Object.keys(n)) visit(peekAt(t, n as Obj, k))
  }
  visit(node)
}

/** Visit every armed entry of the spec with its path, depth first in the spec's order (a refusal, the debugging hook). */
function walkArmed(t: Tracking, f: (r: Rec, i: number, path: string) => void): void {
  const seen = new Set<object>()
  const visit = (node: unknown, path: string): void => {
    if (node === null || typeof node !== 'object' || seen.has(node)) return
    seen.add(node)
    if (Array.isArray(node)) {
      const a = t.arrays.get(node)
      if (a !== undefined) a.elements.forEach((x, i) => visit(x, `${path}[${i}]`))
      return
    }
    const r = recOf(node)
    if (r === undefined || r.t !== t) return
    for (let i = 0; i < r.armed; i++) {
      const at = path ? `${path}.${r.keys[i]!}` : r.keys[i]!
      f(r, i, at)
      if ((r.flags[i]! & TRACKED) === 0) visit(r.values[i], at)
    }
  }
  visit(t.root, '')
}

/** The path of the armed entry `j` of `o`. */
function pathOf(t: Tracking, o: Rec, j: number): string | undefined {
  let found: string | undefined
  walkArmed(t, (r, i, path) => {
    if (found === undefined && r === o && i === j) found = path
  })
  return found
}

/**
 * The paths of the properties of the spec nothing consumed, in the order of the spec (depth first). A property that holds properties
 * is not one of them: it is in use when one below it is, and otherwise the ones below it are reported.
 */
export function unconsumedPaths(): string[] {
  const t = active
  if (t === undefined || t.unread === 0) return []
  const out: string[] = []
  walkArmed(t, (r, i, path) => {
    if ((r.flags[i]! & (TRACKED | CONSUMED)) === TRACKED) out.push(path)
  })
  return out
}

/** Refuse what the compile did not consume: the properties of the spec it accepted and never read. The message names every path. */
export function refuseUnconsumed(): void {
  const paths = unconsumedPaths()
  if (paths.length === 0) return
  const more = paths.length > 1 ? ` (and ${paths.slice(1).join(', ')})` : ''
  throw new VLCompileError(`${paths[0]}: is valid Vega-Lite but @aster-charts/vl does not implement it here, so it would be ignored${more}`)
}
